/* Kanto First - offline service worker (PW1).
 *
 * sw.js is GENERATED by web/gen_sw.py from web/sw.template.js during
 * `make crystal`; edit the template, never sw.js.  The generator replaces the
 * KF_BUNDLE placeholder below with the build stamp: BUILD_REV, the ROM's
 * sha256, and the sha256 of every file in the bundle.  Any change to any of
 * those changes sw.js byte-for-byte, which is what makes the browser install
 * a new worker.
 *
 * Model: one atomic, versioned bundle per build.
 *   install   fetch every PRECACHE file from the network, check each one's
 *             sha256 against the stamp, and only when ALL of them match write
 *             them into cache `kf-<version>`.  Any non-2xx or mismatch fails
 *             the install, so a half bundle (or a bundle mixing two builds)
 *             can never go live.  No skipWaiting here.
 *   activate  delete every other `kf-*` cache, then clients.claim().
 *   fetch     same-scope GETs of bundle files: cache-first from THIS worker's
 *             cache, network fallback (never written back, so the bundle stays
 *             atomic).  presets/*.sav: cached on first fetch, only when the
 *             bytes match the stamp.  Everything else: untouched.
 *   message   'kf-info' -> {build, rom, version, complete, missing};
 *             'kf-skip-waiting' -> skipWaiting(), sent ONLY when the player
 *             taps "Update ready - reload" (offline.js).
 *
 * This worker never touches IndexedDB, localStorage or any cache whose name
 * does not start with `kf-`: the saves are the page's business.
 */
'use strict';

var KF = /*@KF_BUNDLE@*/null;

var CACHE = 'kf-' + KF.version;
var PRECACHE = Object.keys(KF.files);
var SCOPE = self.registration.scope;               // always ends in '/'
var SCOPE_PATH = new URL(SCOPE).pathname;

function abs(rel) { return SCOPE + rel; }

function hex(buf) {
  var b = new Uint8Array(buf), s = '';
  for (var i = 0; i < b.length; i++) { s += (b[i] < 16 ? '0' : '') + b[i].toString(16); }
  return s;
}

function sha256(buf) {
  return crypto.subtle.digest('SHA-256', buf).then(hex);
}

/* Fetch one bundle file, bypassing the HTTP cache, and return a fresh
   Response over the verified bytes (headers kept: binjgb.wasm needs its
   application/wasm Content-Type for instantiateStreaming). */
function fetchVerified(rel, want) {
  return fetch(new Request(abs(rel), { cache: 'no-store', credentials: 'same-origin' })).then(function (r) {
    if (!r.ok || r.type !== 'basic') { throw new Error(rel + ' -> HTTP ' + r.status + ' (' + r.type + ')'); }
    return r.arrayBuffer().then(function (buf) {
      return sha256(buf).then(function (got) {
        if (got !== want) {
          throw new Error(rel + ' does not match this build (sha256 ' + got.slice(0, 12) +
            ', expected ' + want.slice(0, 12) + ')');
        }
        return new Response(buf, { status: r.status, statusText: r.statusText, headers: r.headers });
      });
    });
  });
}

function tellClients(msg) {
  return self.clients.matchAll({ includeUncontrolled: true, type: 'window' }).then(function (cs) {
    cs.forEach(function (c) { c.postMessage(msg); });
  }).catch(function () {});
}

function precache() {
  // A leftover cache of this exact name can only be a failed earlier attempt
  // at this same version (an active worker of this version would mean no
  // install was triggered), so start clean.
  return caches.delete(CACHE).then(function () {
    return Promise.all(PRECACHE.map(function (rel) {
      return fetchVerified(rel, KF.files[rel]).then(function (resp) { return [rel, resp]; });
    }));
  }).then(function (got) {
    return caches.open(CACHE).then(function (cache) {
      return Promise.all(got.map(function (pair) { return cache.put(abs(pair[0]), pair[1]); }));
    });
  }).catch(function (err) {
    return caches.delete(CACHE).catch(function () {}).then(function () {
      return tellClients({ type: 'kf-install-failed', build: KF.build, version: KF.version,
        reason: String(err && err.message ? err.message : err) });
    }).then(function () { throw err; });
  });
}

self.addEventListener('install', function (event) {
  event.waitUntil(precache());
});

self.addEventListener('activate', function (event) {
  event.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) {
      return k.indexOf('kf-') === 0 && k !== CACHE;
    }).map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});

/* Map a request URL to a bundle-relative path, or null if out of scope. */
function relOf(url) {
  var u = new URL(url);
  if (u.origin !== self.location.origin || u.pathname.indexOf(SCOPE_PATH) !== 0) { return null; }
  var rel = u.pathname.slice(SCOPE_PATH.length);
  if (rel === '') { return 'index.html'; }          // "/" is the player
  if (rel === 'edit') { return 'edit.html'; }       // server.py's alias
  return rel;
}

function fromBundle(rel, request) {
  return caches.open(CACHE).then(function (cache) {
    return cache.match(abs(rel));
  }).then(function (hit) {
    // A miss should not happen once installed; go to the network but do not
    // write the answer back - it may be from another build.
    return hit || fetch(request);
  });
}

function preset(rel, request) {
  var want = KF.presets[rel];
  return caches.open(CACHE).then(function (cache) {
    return cache.match(abs(rel)).then(function (hit) {
      if (hit) { return hit; }
      return fetch(request).then(function (r) {
        if (!r.ok || r.type !== 'basic' || !want) { return r; }
        return r.clone().arrayBuffer().then(sha256).then(function (got) {
          // Only bytes of THIS build go into this build's cache.
          return got === want ? cache.put(abs(rel), r.clone()) : null;
        }).catch(function () { return null; }).then(function () { return r; });
      });
    });
  });
}

self.addEventListener('fetch', function (event) {
  var req = event.request;
  if (req.method !== 'GET') { return; }
  var rel = relOf(req.url);
  if (rel === null) { return; }
  if (Object.prototype.hasOwnProperty.call(KF.files, rel)) {
    event.respondWith(fromBundle(rel, req));
  } else if (Object.prototype.hasOwnProperty.call(KF.presets, rel)) {
    event.respondWith(preset(rel, req));
  }
});

function info() {
  return caches.has(CACHE).then(function (have) {
    if (!have) { return PRECACHE.slice(); }
    return caches.open(CACHE).then(function (cache) {
      return Promise.all(PRECACHE.map(function (rel) {
        return cache.match(abs(rel)).then(function (hit) { return hit ? null : rel; });
      }));
    }).then(function (m) { return m.filter(function (x) { return x; }); });
  }).then(function (missing) {
    return { type: 'kf-info', build: KF.build, rom: KF.rom, version: KF.version, cache: CACHE,
      complete: missing.length === 0, missing: missing };
  });
}

self.addEventListener('message', function (event) {
  var d = event.data || {};
  if (d.type === 'kf-skip-waiting') {
    self.skipWaiting();
  } else if (d.type === 'kf-info') {
    var port = event.ports && event.ports[0];
    event.waitUntil(info().then(function (r) {
      if (port) { port.postMessage(r); } else if (event.source) { event.source.postMessage(r); }
    }));
  }
});
